<template>
  <section v-if="state.selected" class="copy-panel" aria-label="区块协作">
    <header class="copy-panel__heading"><div><small>当前选中区块</small><h2>{{ state.selected.label }}</h2></div><button type="button" aria-label="关闭区块协作" :disabled="state.busy" @click="close">×</button></header>
    <p class="copy-panel__context">{{ state.selected.context.page }}<span v-if="location.label"> · {{ location.label }}</span><span v-else-if="state.selected.context.state"> · {{ state.selected.context.state }}</span></p>
    <div class="copy-panel__tabs" role="tablist" aria-label="区块协作方式"><button v-if="editable" type="button" role="tab" :aria-selected="state.tab==='edit'" @click="state.tab='edit'">文案</button><button type="button" role="tab" :aria-selected="state.tab==='comments'" @click="state.tab='comments'">备注 / 评论 <span v-if="state.comments.length">{{ state.comments.length }}</span></button><button v-if="editable" type="button" role="tab" :aria-selected="state.tab==='history'" @click="state.tab='history'">版本记录</button></div>
    <div v-if="state.syncMessage||state.blockMessage" class="copy-panel__sync" role="status"><span>{{ state.blockMessage||'同步暂时延迟，当前内容已保留。' }}</span><button type="button" :disabled="state.busy||state.syncing" @click="refresh">{{ state.syncing?'同步中…':'重新同步' }}</button></div>
    <template>
      <label class="copy-panel__author">显示名称<input v-model="state.actor" maxlength="40" placeholder="用于修改与评论记录" :disabled="state.busy"/><small>此名称由协作者填写。</small></label>
      <form v-if="state.tab==='edit'&&editable" class="copy-panel__form" @submit.prevent="save">
        <section v-if="locations.length" class="copy-location" aria-label="文案使用场景">
          <label for="copy-location-select">文案展示位置</label><select id="copy-location-select" :value="state.location" :disabled="state.busy" @change="preview($event.target.value)"><option v-for="item in locations" :key="item.id" :value="item.id">{{ item.label }}</option></select>
          <p>{{ location.condition }}</p>
          <div><button type="button" :disabled="state.busy" @click="preview(state.location)">{{ state.preview?'重新定位此状态':'预览此状态' }} ↗</button><button v-if="state.preview" type="button" @click="exitPreview">返回原交互</button></div>
          <small v-if="state.preview" role="status">正在预览 · {{ state.preview.label }}<br>切换场景保留草稿，预览不产生订单。</small>
        </section>
        <section v-else-if="state.preview" class="copy-location"><p>正在预览 · {{ state.preview.label }}</p><button type="button" @click="exitPreview">返回原交互</button></section>
        <p class="copy-panel__hint">修改即时预览；保存会一起提交此区块各展示位置的修改。</p>
        <div v-for="field in visibleFields" :key="field.key" :data-copy-field="field.key" class="copy-field" :class="{'has-error':state.errors[field.key]}">
          <label :for="'copy-input-'+field.key"><span>{{ usage(field.key)&&usage(field.key).label||field.label }}</span><small>{{ Array.from(state.draft[field.key]||'').length }} / {{ field.max }}</small></label>
          <textarea :id="'copy-input-'+field.key" :value="state.draft[field.key]" :rows="field.max>160?3:2" :disabled="state.busy" :aria-invalid="!!state.errors[field.key]" @input="edit(field.key,$event.target.value)" @focus="locate(field.key,false)"/>
          <small v-if="state.errors[field.key]" class="copy-field__error">{{ state.errors[field.key] }}</small>
          <small v-else-if="field.tokens.length">保留变量 {{ field.tokens.join('、') }}<template v-if="field.tokens.includes('{days}')">；预览示例为 30 天</template>。</small>
          <div v-if="field.inherit||field.tokens.includes('{days}')" class="copy-field__effective"><small>{{ effective(field).inherited?'沿用通用文案 · 实际显示':'实际显示' }}</small><p>{{ sample(field) }}</p></div>
          <small v-if="usage(field.key)&&usage(field.key).shared" class="copy-field__usage">{{ usage(field.key).shared }}</small>
          <button v-if="locations.length" type="button" class="copy-field__locate" :disabled="state.busy" @click="locate(field.key,true)">在原型中定位 ↗</button>
        </div>
        <p v-if="hiddenDirty" class="copy-panel__hint">另有 {{ hiddenDirty }} 处修改位于其他展示位置，将随此区块一起保存。</p>
        <div class="copy-panel__save"><button type="submit" class="is-primary" :disabled="!dirty||state.busy||state.conflict||(!state.snapshotReady&&!state.blockReady)||Object.keys(state.errors).length>0">{{ state.busy?'保存中…':(!state.snapshotReady&&!state.blockReady)?'等待读取共享版本':'保存此区块' }}</button><button type="button" :disabled="!dirty||state.busy" @click="discard">还原</button></div>
      </form>
      <div v-else-if="state.tab==='comments'" class="copy-comments"><form @submit.prevent="comment"><label>备注 / 评论<textarea v-model="state.commentDraft" maxlength="2000" rows="3" placeholder="描述此处需要调整的内容…" :disabled="state.busy"/></label><button type="submit" class="is-primary" :disabled="state.busy||!state.commentDraft.trim()">提交评论</button></form><p v-if="!state.comments.length" class="copy-panel__hint">这里还没有评论。</p><article v-for="item in state.comments" :key="item.id" :class="{'is-resolved':item.resolved_at}"><header><strong>{{ item.actor }}</strong><time>{{ date(item.created_at) }}</time></header><p>{{ item.body }}</p><small>{{ context(item.context_json) }}</small><button v-if="editable&&!item.resolved_at" type="button" :disabled="state.busy" @click="resolve(item.id)">标记解决</button><span v-else-if="item.resolved_at" class="copy-comment-resolved">已解决</span></article></div>
      <div v-else-if="state.tab==='history'" class="copy-history"><p class="copy-panel__hint">恢复历史内容后，保存为新版本，历史记录会保留。</p><p v-if="!state.versions.length" class="copy-panel__hint">尚无保存记录。</p><article v-for="version in state.versions" :key="version.id"><strong>v{{ version.revision }} · {{ version.actor }}</strong><time>{{ date(version.created_at) }}</time><button type="button" :disabled="state.busy" @click="restore(version)">预览此版本</button></article></div>
    </template>
    <p v-if="state.status" class="copy-panel__status" :class="{'is-conflict':state.conflict}" role="status">{{ state.status }}</p><button v-if="state.conflict" type="button" class="copy-panel__reload" :disabled="state.busy" @click="reload">载入最新版本</button>
    <footer v-if="reviewable" class="copy-panel__footer"><span>{{ state.syncing?'正在同步':state.syncMessage?'同步延迟':state.lastSyncedAt?'最近同步 '+date(state.lastSyncedAt):'等待读取共享版本' }}</span><button type="button" :disabled="state.busy||state.syncing" @click="refresh">刷新</button></footer>
  </section>
</template>
<script>
import {copyState,copyDirty,copyFieldDirty,canEdit,canReview,editCopy,discardCopy,closeCopyBlock,saveCopy,submitComment,resolveComment,previewVersion,reloadCopy} from '@/copy/operations-copy'
import {previewCopyLocation,exitCopyPreview,recoverCopyConnection} from '@/copy/operations-copy'
import {locationsForBlock,fieldUsage,effectiveCopy} from '@/copy/copy-locations.cjs'
export default {
  data:()=>({state:copyState}),
  computed:{editable(){return canEdit(this.state.selected.id)},reviewable(){return canReview(this.state.selected.id)},dirty:copyDirty,locations(){return locationsForBlock(this.state.selected.id)},location(){return this.locations.find(item=>item.id===this.state.location)||{}},visibleFields(){return this.state.fields.filter(field=>this.state.visibleFields.includes(field.key))},hiddenDirty(){return this.state.fields.filter(field=>!this.state.visibleFields.includes(field.key)&&copyFieldDirty(field.key)).length}},
  beforeDestroy(){clearTimeout(this.focusTimer);this.clearFocus()},
  methods:{edit:editCopy,discard:discardCopy,close:closeCopyBlock,save:saveCopy,comment:submitComment,resolve:resolveComment,restore:previewVersion,reload:reloadCopy,exitPreview:exitCopyPreview,usage:fieldUsage,
    effective(field){return effectiveCopy(this.state.values,field)},sample(field){return this.effective(field).value.replace(/\{days\}/g,'30')},
    preview(id){previewCopyLocation(id);this.$nextTick(()=>this.locate(this.state.visibleFields[0],false))},
    clearFocus(){document.querySelectorAll('.copy-field-focus').forEach(element=>element.classList.remove('copy-field-focus'))},
    locate(key,preview){
      if(preview)previewCopyLocation(this.state.location)
      this.$nextTick(()=>{
        this.clearFocus();clearTimeout(this.focusTimer)
        const elements=Array.from(document.querySelectorAll('.phone-frame [data-copy-key]')).filter(element=>element.getAttribute('data-copy-key')===key&&element.getClientRects().length&&getComputedStyle(element).visibility!=='hidden')
        if(!elements.length)return
        elements[0].scrollIntoView({block:'nearest',inline:'nearest'});elements.forEach(element=>element.classList.add('copy-field-focus'));this.focusTimer=setTimeout(()=>this.clearFocus(),4500)
      })
    },
    async refresh(){await recoverCopyConnection(true)},date(value){return new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value))},context(value){try{const c=JSON.parse(value);return [c.page,c.state].filter(Boolean).join(' · ')}catch(_){return ''}}
  }
}
</script>
<style scoped>
.copy-panel__sync{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:16px;padding:9px 10px;border-radius:6px;background:#fff8ed;color:#927343;font-size:11px}.copy-panel__sync>button{flex-shrink:0;background:transparent;border:0;padding:3px;color:#927343}
.copy-location{padding:13px 12px;margin-bottom:20px;background:#fff;border:1px solid #e5e8ed;border-radius:8px}.copy-location>label{display:block;color:#5c6674;font-size:11px;margin-bottom:7px}.copy-location select{width:100%;border:1px solid #dfe3e9;border-radius:6px;padding:8px;background:#fff;color:#465363;font:12px/20px inherit;min-height:36px}.copy-location>p{margin:9px 0;color:#8a929f;font-size:11px;line-height:18px}.copy-location>div{display:flex;gap:5px;flex-wrap:wrap}.copy-location>small{display:block;margin-top:9px;font-size:10px;line-height:17px;color:#ae7165}.copy-field>label{display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:11px;color:#596372;margin-bottom:7px}.copy-field__effective{border-radius:5px;background:#f2f4f7;padding:7px 10px;margin:7px 0}.copy-field__effective p{margin:2px 0 0;font-size:12px;line-height:19px;color:#677180;overflow-wrap:anywhere;white-space:pre-wrap}.copy-field small.copy-field__usage{display:block;margin-top:6px}.copy-field button.copy-field__locate{font-size:10px;line-height:16px;border:0;background:transparent;padding:5px 0;color:#bc7568;margin-top:3px}
.copy-panel{padding-bottom:16px;color:#373e4a;font-family:inherit;font-size:12px;line-height:1.6}.copy-panel__heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.copy-panel__heading small{color:#9399a4;font-size:10px}.copy-panel__heading h2{font-size:17px;line-height:25px;margin:5px 0 0;font-weight:600}.copy-panel button{font-family:inherit;cursor:pointer;border:1px solid #e2e5ea;background:white;border-radius:7px;color:#596372;padding:7px 11px;font-size:11px;line-height:18px}.copy-panel button:disabled{opacity:.5;cursor:default}.copy-panel__heading>button{font-size:21px;line-height:25px;padding:0 7px;border:0;background:transparent}.copy-panel__context{font-size:11px;line-height:18px;color:#8a929f;margin:8px 0 16px;overflow-wrap:anywhere}.copy-panel__tabs{display:flex;border-bottom:1px solid #e9ebef;gap:16px;margin-bottom:20px}.copy-panel__tabs button{padding:10px 0;border:0;border-bottom:2px solid transparent;border-radius:0;font-size:12px;background:none}.copy-panel__tabs button[aria-selected=true]{color:#c8463d;border-bottom-color:#dd554a;font-weight:600}.copy-panel__tabs span{font-size:10px}.copy-panel__author{display:block;font-size:11px;color:#75808e;margin-bottom:18px}.copy-panel input,.copy-panel textarea{display:block;width:100%;box-sizing:border-box;padding:9px 11px;border:1px solid #dfe3e9;border-radius:7px;background:#fff;color:#39414c;font-family:inherit;font-size:12px;line-height:1.6;outline:none;resize:vertical}.copy-panel input:focus,.copy-panel textarea:focus{border-color:#da6e64;box-shadow:0 0 0 3px #d6544910}.copy-panel input{margin-top:6px}.copy-panel__author>small{font-size:10px;color:#a1a7b0}.copy-panel__hint{color:#8a929f;font-size:11px;line-height:18px;margin:0 0 16px}.copy-field{display:block;margin-bottom:20px}.copy-field>span{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;color:#596372;font-size:11px}.copy-field small{font-size:10px;color:#a1a7b0}.copy-field.has-error textarea{border-color:#d25b50}.copy-field small.copy-field__error{color:#c8463d}.copy-panel button.is-primary{color:#fff;background:#d75046;border-color:#d75046}.copy-panel__save{position:sticky;bottom:0;display:flex;gap:8px;background:#fbfcfeee;padding:14px 0;border-top:1px solid #eaecf0;z-index:1}.copy-panel__save>button:first-child{flex:1}.copy-panel__status{font-size:11px;line-height:18px;padding:11px 12px;border-radius:7px;background:#f1f5f0;color:#62805e;overflow-wrap:anywhere}.copy-panel__status.is-conflict{background:#fff6e8;color:#9c752e}.copy-panel__reload{width:100%}.copy-panel__footer{margin-top:24px;display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:10px;color:#a0a7b2}.copy-panel__footer button{padding:3px 7px;border:0;background:none}.copy-comments form>label{font-size:11px;color:#738090}.copy-comments textarea{margin:6px 0 10px}.copy-comments form>button{display:block;margin-left:auto}.copy-comments article,.copy-history article{padding:18px 0;border-bottom:1px solid #e9ecf0}.copy-comments article header{display:flex;justify-content:space-between;align-items:center;gap:8px}.copy-comments strong,.copy-history strong{font-size:11px;font-weight:600}.copy-comments time,.copy-history time{font-size:10px;color:#9ca4b0}.copy-comments article p{font-size:12px;line-height:20px;white-space:pre-wrap;overflow-wrap:anywhere;color:#5b6574;margin:9px 0}.copy-comments article>small{display:block;color:#9ca4b0;font-size:10px}.copy-comments article>button{font-size:10px;border:0;padding:4px 0;color:#bd7866;background:none}.copy-comments article.is-resolved{opacity:.65}.copy-comment-resolved{font-size:10px;color:#82967b}.copy-history article time{display:block;margin:4px 0 9px}.copy-history article button{font-size:10px}.copy-panel__locked{padding:20px 16px;background:#f4f6f8;border:1px solid #e8ebef;border-radius:9px;font-size:12px;color:#737e8d}.copy-panel__locked small{font-size:10px;color:#9da5b0}
</style>
